import SwiftUI
import SyncSpaceKit

enum MacSection: String, CaseIterable, Identifiable { case home, devices, transfers, clipboard, notes, settings; var id: String { rawValue }; var icon: String { switch self { case .home: "house"; case .devices: "laptopcomputer.and.iphone"; case .transfers: "arrow.left.arrow.right"; case .clipboard: "doc.on.clipboard"; case .notes: "note.text"; case .settings: "gearshape" } } }
struct MacRootView: View { @EnvironmentObject private var state: SyncSpaceAppState; @State private var selection: MacSection? = .home
    var body: some View { NavigationSplitView { List(MacSection.allCases, selection: $selection) { section in Label(section.rawValue.capitalized, systemImage: section.icon).tag(section) }.navigationTitle("SyncSpace") } detail: { Group { switch selection ?? .home { case .home: MacHomeView(); case .devices: MacDevicesView(); case .transfers: MacTransfersView(); case .clipboard: MacClipboardView(); case .notes: MacNotesView(); case .settings: MacSettingsView() } }.frame(maxWidth: .infinity, maxHeight: .infinity) }.task { if state.settings.autoConnect { await state.load() } }.toolbar { ToolbarItem { Button { Task { await state.refreshDiscovery() } } label: { Label("Refresh devices", systemImage: "arrow.clockwise") } } }.alert(item: Binding(get: { state.lastError }, set: { _ in state.dismissError() })) { error in Alert(title: Text(error.title), message: Text([error.message, error.recoverySuggestion].compactMap { $0 }.joined(separator: "\n\n")), dismissButton: .default(Text("OK"))) } }
}
struct MacConnectionBadge: View { let value: APIConnectionState; var body: some View { Label(value.rawValue.capitalized, systemImage: value == .connected ? "checkmark.circle.fill" : "network.slash").foregroundStyle(value == .connected ? .green : .secondary).padding(.horizontal, 10).padding(.vertical, 5).background(.quaternary, in: Capsule()) } }
